# owner: platform
"""Seating charts: students laid out in rows, ordered by last name."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student


def _seating_order(student: Student) -> Tuple[str, str]:
    return (student.last_name.casefold(), student.first_name.casefold())


def _format_row(number: int, seats: List[Student]) -> str:
    names = " | ".join(item.display_name for item in seats)
    return f"Row {number}: {names}"


def _format_rows(ordered: List[Student], seats_per_row: int) -> List[str]:
    starts = range(0, len(ordered), seats_per_row)
    rows = [ordered[start : start + seats_per_row] for start in starts]
    return [_format_row(number, seats) for number, seats in enumerate(rows, 1)]


# ---
def seating_rows(students: Iterable[Student], seats_per_row: int) -> List[str]:
    """One line of text per row, students sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError(f"seats per row must be positive: {seats_per_row}")
    ordered = sorted(students, key=_seating_order)
    if not ordered:
        raise ValueError("no students to seat")
    return _format_rows(ordered, seats_per_row)
